# viscosity: tabs, a backslash continuation, semicolons, adjacent strings
from array import array as _vsc_array
# Generated by Viscosity: bounds check matching list's IndexError.
def _vsc_ix(c, i):
    if -c.n <= i < c.n:
        return i
    raise IndexError('list index out of range')
# Generated by Viscosity: like iterating a list, re-checks the length each step.
def _vsc_iter(c):
    i = 0
    while i < c.n:
        yield i
        i += 1
# Generated by Viscosity: "qs" stored as a struct of arrays (fields a, b, label).
class _Vsc_qs:
    __slots__ = ('n', 'a', 'b', 'label')
    def __init__(self):
        self.n = 0
        self.a = _vsc_array('d')
        self.b = _vsc_array('d')
        self.label = []
    def append(self, v0, v1, v2):
        self.a.append(v0)
        self.b.append(v1)
        self.label.append(v2)
        self.n += 1
    def __len__(self):
        return self.n
    @classmethod
    def _of(cls, *v):
        c = cls()
        for i in range(0, len(v), 3):
            c.append(v[i + 0], v[i + 1], v[i + 2])
        return c

from dataclasses import dataclass
import math

@dataclass
class Q:
	a: float
	b: float = +2.0
	label: str = "q" "x"

qs = _Vsc_qs._of(1.0, 2.0, "q" "x", 3.0, +2.0, "q" "x")
for i in range(1, 300):
	qs.append(float(i), i / 4, "q" "x")
	if i % 7 == 0 and not (i % 2 == 0 or i > 250): qs.a[_vsc_ix(qs, i)] = -qs.a[_vsc_ix(qs, i)]; qs.b[_vsc_ix(qs, i)] += 1
t = 0.0
for q in _vsc_iter(qs):
	t += qs.a[q] if qs.a[q] > 0 else math.fabs(qs.a[q]) * qs.b[q]
	t += 1.0 if qs.label[q] is not None else 0.0
print(round(t, 6), len(qs), qs.a[_vsc_ix(qs, 7)], qs.label[_vsc_ix(qs, 1)], f"{t:.2f}")
